import { useCallback, useEffect, useRef, useState } from "react";
import { lerp, clamp, ease } from "./helpers";

// ─── ix/iy = % of the rendered india.png image (pixel-measured from reference exports)
// anchor: "left"  → label sits in the LEFT column, line goes right → dot
//         "right" → label sits in the RIGHT column, line goes left → dot
//         "bottom"→ label sits below the map (centred)
const MAP_DATA = {
  default: [
    { label: "Gujarat",     pct: "6.63%", ix: 31.1, iy: 42.5, anchor: "left"   },
    { label: "Haryana",     pct: "4.92%", ix: 65.4, iy: 39.7, anchor: "right"  },
    { label: "Maharashtra", pct: "7.75%", ix: 41.0, iy: 56.1, anchor: "left"   },
    { label: "Karnataka",   pct: "3.48%", ix: 60.0, iy: 66.7, anchor: "right"  },
    { label: "Kerala",      pct: "8.42%", ix: 55.6, iy: 76.4, anchor: "left"   },
  ],
  truck: [
    { label: "Haryana",       pct: "5.01%", ix: 44.4, iy: 40.0, anchor: "right"  },
    { label: "Uttar Pradesh", pct: "2.73%", ix: 53.8, iy: 44.9, anchor: "left"   },
    { label: "Telangana",     pct: "2.56%", ix: 50.6, iy: 63.1, anchor: "left"   },
    { label: "Karnataka",     pct: "3.71%", ix: 43.7, iy: 68.9, anchor: "right"  },
    { label: "Tamil Nadu",    pct: "3.80%", ix: 50.9, iy: 75.0, anchor: "bottom" },
  ],
  darkstore: [
    { label: "Haryana",     pct: "4.38%", ix: 36.8, iy: 39.9, anchor: "right"  },
    { label: "Gujarat",     pct: "4.47%", ix: 26.7, iy: 52.5, anchor: "left"   },
    { label: "Maharashtra", pct: "5.38%", ix: 34.6, iy: 59.6, anchor: "left"   },
    { label: "Karnataka",   pct: "3.22%", ix: 36.3, iy: 69.3, anchor: "right"  },
    { label: "Tamil Nadu",  pct: "1.94%", ix: 43.5, iy: 75.6, anchor: "bottom" },
  ],
  delivery: [
    { label: "Gujarat",        pct: "6.22%", ix: 24.9, iy: 46.2, anchor: "left"   },
    { label: "Madhya Pradesh", pct: "2.05%", ix: 38.8, iy: 46.2, anchor: "right"  },
    { label: "Maharashtra",    pct: "7.49%", ix: 32.6, iy: 53.1, anchor: "left"   },
    { label: "Karnataka",      pct: "3.54%", ix: 34.8, iy: 62.9, anchor: "right"  },
    { label: "Tamil Nadu",     pct: "2.51%", ix: 42.0, iy: 69.1, anchor: "bottom" },
  ],
};

const SEGMENTS = [
  {
    title: "Truck Drivers",
    mapKey: "truck",
    content:
      "Truck drivers face elevated risk due to long-haul travel, extended driving hours, highway exposure, and fatigue-related incidents across inter‑state routes.",
  },
  {
    title: "Dark Store Workers",
    mapKey: "darkstore",
    content:
      "Dark store workers experience localized operational risk driven by dense urban locations, late‑night activity, inventory movement, and limited on‑ground supervision.",
  },
  {
    title: "Delivery Partners",
    mapKey: "delivery",
    content:
      "Delivery partners encounter frequent risk events due to high trip volumes, time‑bound deliveries, traffic violations, and continuous exposure to congested city roads.",
  },
];

// ─── Hook: actual rendered image bounds inside objectFit:contain container
function useImageBounds(imgRef, containerRef) {
  const [bounds, setBounds] = useState(null);

  const compute = useCallback(() => {
    const img = imgRef.current;
    const box = containerRef.current;
    if (!img || !box || !img.naturalWidth || !img.naturalHeight) return;
    const cw = box.clientWidth;
    const ch = box.clientHeight;
    const scale = Math.min(cw / img.naturalWidth, ch / img.naturalHeight);
    const rw = img.naturalWidth  * scale;
    const rh = img.naturalHeight * scale;
    setBounds({ left: (cw - rw) / 2, top: (ch - rh) / 2, width: rw, height: rh });
  }, [imgRef, containerRef]);

  useEffect(() => {
    const img = imgRef.current;
    if (!img) return;
    if (img.complete && img.naturalWidth) compute();
    else img.addEventListener("load", compute);
    const ro = new ResizeObserver(compute);
    if (containerRef.current) ro.observe(containerRef.current);
    window.addEventListener("resize", compute);
    return () => {
      img.removeEventListener("load", compute);
      ro.disconnect();
      window.removeEventListener("resize", compute);
    };
  }, [compute, containerRef, imgRef]);

  return bounds;
}

// ─── Dots-only SVG overlay (no labels, no lines — those live outside the map)
function DotsLayer({ hotspots, bounds, visible }) {
  if (!bounds) return null;

  const toPx = (ix, iy) => ({
    x: bounds.left + (ix / 100) * bounds.width,
    y: bounds.top  + (iy / 100) * bounds.height,
  });

  return (
    <div
      style={{
        position: "absolute", inset: 0, pointerEvents: "none",
        opacity: visible ? 1 : 0, transition: "opacity 0.32s ease",
      }}
    >
      <svg style={{ position: "absolute", inset: 0, width: "100%", height: "100%", overflow: "visible" }}>
        <defs>
          <radialGradient id="glowOuter" cx="50%" cy="50%" r="50%">
            <stop offset="0%"   stopColor="#ff6600" stopOpacity="0.55" />
            <stop offset="100%" stopColor="#880000" stopOpacity="0"    />
          </radialGradient>
          <radialGradient id="glowCore" cx="50%" cy="50%" r="50%">
            <stop offset="0%"   stopColor="#ffffff" stopOpacity="1"    />
            <stop offset="40%"  stopColor="#ff8800" stopOpacity="0.95" />
            <stop offset="100%" stopColor="#cc2200" stopOpacity="0"    />
          </radialGradient>
        </defs>
        {hotspots.map((h, i) => {
          const { x, y } = toPx(h.ix, h.iy);
          return (
            <g key={i}>
              <circle cx={x} cy={y} r="20" fill="url(#glowOuter)" />
              <circle cx={x} cy={y} r="10" fill="url(#glowCore)"  />
              <circle cx={x} cy={y} r="5"  fill="#ff4400" opacity="0.9" />
              <circle cx={x} cy={y} r="2"  fill="white" />
            </g>
          );
        })}
      </svg>
    </div>
  );
}

// ─── Side label column (left or right) with connector lines
function LabelColumn({ hotspots, side, bounds, visible, mapContainerRef }) {
  const filtered = hotspots.filter((h) => h.anchor === side);
  const [labelPositions, setLabelPositions] = useState({});

  // Function to convert percentage coordinates to pixel positions
  const toPx = (ix, iy) => {
    if (!bounds) return { x: 0, y: 0 };
    return {
      x: bounds.left + (ix / 100) * bounds.width,
      y: bounds.top + (iy / 100) * bounds.height,
    };
  };

  // Update label positions after render
  useEffect(() => {
    if (!visible) return;

    const updatePositions = () => {
      const positions = {};
      filtered.forEach((h) => {
        const element = document.querySelector(`[data-label="${side}-${h.label}"]`);
        if (element && mapContainerRef?.current) {
          const rect = element.getBoundingClientRect();
          const containerRect = mapContainerRef.current.parentElement?.getBoundingClientRect();
          if (containerRect) {
            positions[h.label] = {
              x: rect.left + (side === "left" ? rect.width : 0) - containerRect.left,
              y: rect.top + rect.height / 2 - containerRect.top,
            };
          }
        }
      });
      setLabelPositions(positions);
    };

    updatePositions();
    window.addEventListener("resize", updatePositions);
    return () => window.removeEventListener("resize", updatePositions);
  }, [filtered, side, visible, mapContainerRef]);

  return (
    <div
      style={{
        position: "relative",
        width: 140,
        height: "100%",
        flexShrink: 0,
        opacity: visible ? 1 : 0,
        transition: "opacity 0.32s ease",
      }}
    >
      {/* Vertical pipe divider */}
      <div
        style={{
          position: "absolute",
          top: 0,
          bottom: 0,
          [side === "left" ? "right" : "left"]: 0,
          width: 2,
          background: "rgba(204, 0, 0, 0.6)",
          borderRadius: 1,
        }}
      />

      {/* SVG for connector lines */}
      {bounds && visible && (
        <svg
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            pointerEvents: "none",
            overflow: "visible",
            zIndex: 5,
          }}
        >
          {filtered.map((h, i) => {
            const dotPos = toPx(h.ix, h.iy);
            const labelPos = labelPositions[h.label];

            if (!labelPos) return null;

            // Calculate line start/end positions
            let startX, startY, endX, endY;

            if (side === "left") {
              // Line from label to dot (rightward from label to map)
              startX = labelPos.x;
              startY = labelPos.y;
              endX = dotPos.x - 8;
              endY = dotPos.y;
            } else {
              // Line from label to dot (leftward from label to map)
              startX = labelPos.x;
              startY = labelPos.y;
              endX = dotPos.x + 8;
              endY = dotPos.y;
            }

            return (
              <line
                key={i}
                x1={startX}
                y1={startY}
                x2={endX}
                y2={endY}
                stroke="#cc0000"
                strokeWidth="2"
                strokeDasharray="5 3"
                style={{
                  strokeLinecap: "round",
                }}
              />
            );
          })}
        </svg>
      )}

      {filtered.map((h, i) => {
        const topPct = h.iy;

        return (
          <div
            key={i}
            data-label={`${side}-${h.label}`}
            style={{
              position: "absolute",
              top: `${topPct}%`,
              transform: "translateY(-50%)",
              [side === "left" ? "right" : "left"]: 16,
              textAlign: side === "left" ? "right" : "left",
              fontFamily: "'Inter','Helvetica Neue',sans-serif",
              whiteSpace: "nowrap",
              zIndex: 10,
            }}
          >
            {/* Horizontal tick line toward the pipe */}
            <div
              style={{
                position: "absolute",
                top: "50%",
                transform: "translateY(-50%)",
                [side === "left" ? "right" : "left"]: -12,
                width: 8,
                height: 2,
                background: "#cc0000",
                borderRadius: 1,
              }}
            />
            <div
              style={{
                background: "rgba(0, 0, 0, 0.8)",
                backdropFilter: "blur(8px)",
                padding: "6px 14px",
                borderRadius: 24,
                border: "1px solid rgba(204, 0, 0, 0.4)",
                boxShadow: "0 2px 8px rgba(0,0,0,0.3)",
              }}
            >
              <div
                style={{
                  fontSize: "clamp(14px, 1.4vw, 19px)",
                  fontWeight: 700,
                  color: "#ff6600",
                  lineHeight: 1.2,
                }}
              >
                {h.pct}
              </div>
              <div
                style={{
                  fontSize: "clamp(10px, 0.9vw, 12px)",
                  color: "rgba(255,255,255,0.85)",
                  marginTop: 2,
                  fontWeight: 500,
                }}
              >
                {h.label}
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ─── Bottom label row (for Tamil Nadu / bottom-anchored states) with connector lines
function BottomLabels({ hotspots, bounds, visible, mapContainerRef }) {
  const filtered = hotspots.filter((h) => h.anchor === "bottom");
  const [labelPositions, setLabelPositions] = useState({});

  if (!filtered.length) return null;

  const toPx = (ix, iy) => {
    if (!bounds) return { x: 0, y: 0 };
    return {
      x: bounds.left + (ix / 100) * bounds.width,
      y: bounds.top + (iy / 100) * bounds.height,
    };
  };

  // Update label positions after render
  useEffect(() => {
    if (!visible) return;

    const updatePositions = () => {
      const positions = {};
      filtered.forEach((h) => {
        const element = document.querySelector(`[data-bottom-label="${h.label}"]`);
        if (element && mapContainerRef?.current) {
          const rect = element.getBoundingClientRect();
          const containerRect = mapContainerRef.current.parentElement?.getBoundingClientRect();
          if (containerRect) {
            positions[h.label] = {
              x: rect.left + rect.width / 2 - containerRect.left,
              y: rect.top - containerRect.top,
            };
          }
        }
      });
      setLabelPositions(positions);
    };

    updatePositions();
    window.addEventListener("resize", updatePositions);
    return () => window.removeEventListener("resize", updatePositions);
  }, [filtered, visible, mapContainerRef]);

  return (
    <div
      style={{
        position: "relative",
        display: "flex",
        justifyContent: "center",
        gap: 48,
        marginTop: 16,
        opacity: visible ? 1 : 0,
        transition: "opacity 0.32s ease",
        paddingTop: 8,
      }}
    >
      {/* SVG for connector lines from bottom labels */}
      {bounds && visible && (
        <svg
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            pointerEvents: "none",
            overflow: "visible",
            zIndex: 5,
          }}
        >
          {filtered.map((h, i) => {
            const dotPos = toPx(h.ix, h.iy);
            const labelPos = labelPositions[h.label];

            if (!labelPos) return null;

            return (
              <line
                key={i}
                x1={labelPos.x}
                y1={labelPos.y}
                x2={dotPos.x}
                y2={dotPos.y}
                stroke="#cc0000"
                strokeWidth="2"
                strokeDasharray="5 3"
                style={{
                  strokeLinecap: "round",
                }}
              />
            );
          })}
        </svg>
      )}

      {filtered.map((h, i) => (
        <div
          key={i}
          data-bottom-label={h.label}
          style={{
            textAlign: "center",
            fontFamily: "'Inter','Helvetica Neue',sans-serif",
            background: "rgba(0, 0, 0, 0.8)",
            backdropFilter: "blur(8px)",
            padding: "6px 16px",
            borderRadius: 24,
            border: "1px solid rgba(204, 0, 0, 0.4)",
            minWidth: 100,
            boxShadow: "0 2px 8px rgba(0,0,0,0.3)",
            zIndex: 10,
          }}
        >
          {/* Small upward tick */}
          <div
            style={{
              width: 2,
              height: 12,
              background: "#cc0000",
              margin: "0 auto 6px",
              borderRadius: 1,
            }}
          />
          <div
            style={{
              fontSize: "clamp(14px, 1.4vw, 19px)",
              fontWeight: 700,
              color: "#ff6600",
              lineHeight: 1.2,
            }}
          >
            {h.pct}
          </div>
          <div
            style={{
              fontSize: "clamp(10px, 0.9vw, 12px)",
              color: "rgba(255,255,255,0.85)",
              marginTop: 2,
              fontWeight: 500,
            }}
          >
            {h.label}
          </div>
        </div>
      ))}
    </div>
  );
}

// ─── Main section
export default function GeographicSection() {
  const [openIndex, setOpenIndex] = useState(0);
  const [activeKey, setActiveKey] = useState("truck");
  const [hsVisible, setHsVisible] = useState(true);
  const [progress, setProgress] = useState(0);
  const [mapHeight, setMapHeight] = useState(0);

  const sectionRef = useRef(null);
  const mapContainerRef = useRef(null);
  const mapImgRef = useRef(null);

  const imgBounds = useImageBounds(mapImgRef, mapContainerRef);

  // Track map container height so label columns can match it
  useEffect(() => {
    if (!mapContainerRef.current) return;
    const ro = new ResizeObserver(() => {
      setMapHeight(mapContainerRef.current?.clientHeight || 0);
    });
    ro.observe(mapContainerRef.current);
    setMapHeight(mapContainerRef.current.clientHeight);
    return () => ro.disconnect();
  }, []);

  const switchMap = (newKey) => {
    if (newKey === activeKey) return;
    setHsVisible(false);
    setTimeout(() => {
      setActiveKey(newKey);
      setHsVisible(true);
    }, 320);
  };

  const handleSegmentClick = (index) => {
    const isOpen = openIndex === index;
    setOpenIndex(isOpen ? null : index);
    if (!isOpen) switchMap(SEGMENTS[index].mapKey);
  };

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      setProgress(clamp(-rect.top / (el.offsetHeight - window.innerHeight), 0, 1));
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const titleP = ease(clamp(progress / 0.2, 0, 1));
  const leftP = ease(clamp((progress - 0.2) / 0.25, 0, 1));
  const mapP = ease(clamp((progress - 0.2) / 0.3, 0, 1));

  const hotspots = MAP_DATA[activeKey];

  return (
    <div ref={sectionRef} style={{ height: "350vh", position: "relative" }}>
      <div
        style={{
          position: "sticky",
          top: 0,
          height: "135vh",
          overflow: "hidden",
          background: "black",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          padding: "72px 56px 40px",
        }}
      >
        {/* Background ellipse */}
        <div style={{ position: "absolute", top: 0, left: -450, zIndex: 0 }}>
          <img src="/assets/Ellipse.png" alt="" style={{ width: 900, height: 900 }} />
        </div>

        {/* Title */}
        <div
          style={{
            textAlign: "center",
            marginBottom: 8,
            opacity: titleP,
            transform: `translateY(${lerp(24, 0, titleP)}px)`,
          }}
        >
          <h2
            style={{
              fontFamily: "'Inter','Helvetica Neue',sans-serif",
              fontSize: "105px",
              fontWeight: 700,
              color: "white",
              margin: 0,
              lineHeight: 1.05,
            }}
          >
            Geographic Risk
            <br />
            Concentration
          </h2>
          <p
            style={{
              color: "white",
              fontSize: 18,
              margin: "12px 0 0",
              fontFamily: "'Inter',sans-serif",
            }}
          >
            A breakdown of states with the highest risk rates across India.
          </p>
        </div>

        {/* Body grid: accordion left | map+labels right */}
        <div className="grid grid-cols-1 lg:grid-cols-[320px_1fr] gap-12 w-full max-w-[1200px] flex-1 mt-6">
          {/* ── Left panel: description + accordion ── */}
          <div
            style={{
              opacity: leftP,
              transform: `translateX(${lerp(-24, 0, leftP)}px)`,
              display: "flex",
              flexDirection: "column",
              gap: 20,
              paddingTop: 8,
            }}
          >
            <p
              style={{
                color: "white",
                fontSize: 16,
                lineHeight: 1.7,
                fontFamily: "'Inter',sans-serif",
                margin: 0,
                paddingLeft: 12,
              }}
            >
              Kerala records the highest risk rate in the country, with Maharashtra close behind,
              making them two of the highest risk concentration states across segments.
            </p>
            <p
              style={{
                color: "white",
                fontSize: 16,
                lineHeight: 1.7,
                fontFamily: "'Inter',sans-serif",
                margin: 0,
                paddingLeft: 12,
              }}
            >
              Another contributing factor behind this surge could be stronger crime reporting
              mechanisms in southern and western states. For example, in Kerala, many challans are
              automatically generated through AI-enabled monitoring cameras at traffic junctions.
            </p>

            {/* Accordion */}
            <div style={{ marginTop: 8, display: "flex", flexDirection: "column", gap: 10 }}>
              {SEGMENTS.map((item, i) => {
                const isOpen = openIndex === i;
                return (
                  <div key={i}>
                    <div
                      onClick={() => handleSegmentClick(i)}
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 10,
                        cursor: "pointer",
                        userSelect: "none",
                        color: "white",
                        fontSize: 17,
                        fontWeight: 600,
                        fontFamily: "'Inter',sans-serif",
                        opacity: openIndex !== null && !isOpen ? 0.38 : 1,
                        transition: "opacity 0.25s ease",
                      }}
                    >
                      <span
                        style={{
                          display: "inline-block",
                          transform: isOpen ? "rotate(90deg)" : "rotate(0deg)",
                          transition: "transform 0.25s ease",
                        }}
                      >
                        ▶
                      </span>
                      {item.title}
                    </div>
                    <div
                      style={{
                        display: "grid",
                        gridTemplateRows: isOpen ? "1fr" : "0fr",
                        transition: "grid-template-rows 0.3s ease",
                      }}
                    >
                      <div style={{ overflow: "hidden" }}>
                        <div
                          style={{
                            marginLeft: 22,
                            marginTop: 6,
                            marginBottom: 4,
                            color: "rgba(255,255,255,0.75)",
                            fontSize: 14,
                            lineHeight: 1.6,
                            fontFamily: "'Inter',sans-serif",
                          }}
                        >
                          {item.content}
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* ── Right panel: [left-labels | map | right-labels] ── */}
          <div
            style={{
              opacity: mapP,
              transform: `scale(${lerp(0.94, 1, mapP)})`,
              display: "flex",
              flexDirection: "column",
              height: "100%",
              maxHeight: 520,
            }}
          >
            {/* Three-column map row */}
            <div
              style={{
                display: "flex",
                flex: 1,
                alignItems: "stretch",
                gap: 0,
                minHeight: 0,
              }}
            >
              {/* LEFT label column */}
              <LabelColumn
                hotspots={hotspots}
                side="left"
                mapHeight={mapHeight}
                bounds={imgBounds}
                visible={hsVisible}
                mapContainerRef={mapContainerRef}
              />

              {/* Map (fills remaining space) */}
              <div ref={mapContainerRef} style={{ position: "relative", flex: 1, minWidth: 0 }}>
                <img
                  ref={mapImgRef}
                  src="/assets/india.png"
                  alt="India map"
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "contain",
                    objectPosition: "center",
                    display: "block",
                    filter: "brightness(0.9)",
                  }}
                />
                {/* Only dots on the map — no labels, no connector lines */}
                <DotsLayer hotspots={hotspots} bounds={imgBounds} visible={hsVisible} />
              </div>

              {/* RIGHT label column */}
              <LabelColumn
                hotspots={hotspots}
                side="right"
                mapHeight={mapHeight}
                bounds={imgBounds}
                visible={hsVisible}
                mapContainerRef={mapContainerRef}
              />
            </div>

            {/* BOTTOM labels (Tamil Nadu etc.) */}
            <BottomLabels
              hotspots={hotspots}
              bounds={imgBounds}
              visible={hsVisible}
              mapContainerRef={mapContainerRef}
            />
          </div>
        </div>
      </div>
    </div>
  );
}
